#### 1. Access Control Issues
**Vulnerability Type:** Access control issues
**Severity:** Medium
**Affected Code Location:** `Invoke` function (line 21)
**Description:** The `Invoke` function does not perform any access control checks. It directly executes the function based on the input provided by the user. This can lead to unauthorized access to sensitive operations.
**Recommended Fix:** Implement access control checks to ensure that only authorized users can execute certain functions. For example, you can use a whitelist of allowed functions or roles.

```go
func (t *Chaincode) Invoke(stub shim.ChaincodeStubInterface) pb.Response {
	// Access control check
	allowedFunctions := []string{"addTransaction", "getTransactions"}
	function, args := stub.GetFunctionAndParameters()
	if len(args) != 1 {
		return shim.Error("Incorrect number of arguments. Expecting key of the var to query")
	}
	fmt.Printf("In Invoke with function %s", function)

	if !contains(allowedFunctions, function) {
		return shim.Error("Unauthorized function call")
	}

	err := json.Unmarshal([]byte(args[0]), &t.Msg)
	if err != nil {
		return shim.Error("[Invoke] unable to unmarshall args[0]: " + err.Error())
	}

	if t.FMap[function] != nil {
		fargs := CCFuncArgs{function: function, msg: t.Msg, stub: stub}
		return t.FMap[function](fargs)
	}

	fmt.Printf("BEACON Received unknown invoke function name - %s" + function)
	return shim.Error("BEACON Received unknown invoke function name - '" + function + "'")
}

func contains(slice []string, item string) bool {
	for _, s := range slice {
		if s == item {
			return true
		}
	}
	return false
}
